AddCSLuaFile()AddCSLuaFile("autorun/ery_machine_base_helpers.lua")include("autorun/ery_machine_base_helpers.lua")if SERVER then util.AddNetworkString("DoSafeExplosionParticles")end ENT.Type="anim"ENT.Author="Paloma"ENT.Category="Pointshop Entities"ENT.Spawnable = false ENT.AdminOnly=false ENT.Base="sci_pointshop_entity_base_noui"ENT.PrintName="Safe Explosion"ENT.IconPath="entities/ery_mat_gunpowder.png"ENT.BaseModel="models/hunter/plates/plate.mdl"ENT.BaseMaterial="models/effects/intro_tearshape"ENT.BaseColor=Color(255,255,255,255)ENT.BoneScale=Vector(1,1,1)ENT.AttachmentDrawDistance=1 ENT.LabelDrawDistance=1 ENT.IconOffset=Vector(0,0,0)ENT.CollideSounds={"physics/wood/wood_solid_impact_soft1.wav";"physics/wood/wood_solid_impact_soft2.wav","physics/wood/wood_solid_impact_soft3.wav","physics/wood/wood_solid_impact_soft3.wav"}ENT.Attachments={}if SERVER then function ENT.Initialize(C)C:SetModel(C.BaseModel or"models/hunter/blocks/cube025x025x025.mdl")C:SetMaterial(C.BaseMaterial or"hunter/myplastic")C:SetColor(C.BaseColor or Color(255,255,255,255))C:ManipulateBoneScale(0,C.BoneScale or Vector(1,1,1))C.CollideSounds=C.CollideSounds or(C:GetTable()).CollideSounds C:PhysicsInit(SOLID_VPHYSICS)C:SetMoveType(MOVETYPE_VPHYSICS)C:SetSolid(SOLID_VPHYSICS)C:SetUseType(SIMPLE_USE)local J=C:GetPhysicsObject()timer.Simple(.01,function()if IsValid(J)then J:SetMass(5)J:Wake()end end)timer.Simple(.02,function()if IsValid(C)then C:Kaboom()end end)end end function ENT.Kaboom(C)if C.HasExploded then return end C.HasExploded=true C:EmitSound("phx/explode0"..(math.random(1,5)..".wav"),100,math.random(90,110))local J=C:GetPos()local A=EffectData()A:SetOrigin(J)util.Effect("Explosion",A)if SERVER then net.Start("DoSafeExplosionParticles")net.WriteEntity(C)net.Broadcast()end timer.Simple(.15,function()if not IsValid(C)then return end local J=ents.Create("ery_shockwave")if IsValid(J)then J:SetPos(C:GetPos()+Vector(0,0,10))J:Spawn()end C:Remove()end)end if CLIENT then net.Receive("DoSafeExplosionParticles",function()local C=net.ReadEntity()if not IsValid(C)then return end local J=ParticleEmitter(C:GetPos())for A=1,30,1 do local U=A<=25 local u=J:Add("particle/smokesprites_000"..math.random(1,9),C:GetPos()+Vector(0,0,3))if u then u:SetRoll(math.Rand(0,360))u:SetRollDelta(math.Rand(-1,1))u:SetCollide(true)if U then u:SetVelocity(Vector(math.random(-15,15),math.random(-15,15),math.random(-30,30))*100)u:SetStartAlpha(math.Rand(85,125))u:SetEndAlpha(0)u:SetDieTime(math.Rand(5,7))u:SetStartSize(math.Rand(60,80))u:SetEndSize(math.Rand(10,40))u:SetAirResistance(1500)u:SetColor(50,50,50)u:SetGravity((VectorRand()):GetNormalized()*math.random(-1,1)+Vector(math.random(-10,10),math.random(-10,10),math.random(0,1)))else local C=Vector(math.Rand(-10,10),math.Rand(-10,10),math.Rand(20,70))u:SetVelocity(C*30)u:SetStartAlpha(170)u:SetEndAlpha(35)u:SetDieTime(math.Rand(5,7))u:SetStartSize(math.Rand(5,25))u:SetEndSize(math.Rand(1,2))u:SetAirResistance(250)u:SetColor(69,62,53)u:SetGravity(Vector(0,0,-800))end end end J:Finish()end)end
